"use client";
import { ResearchHeader } from "@/components/research/ResearchHeader";
import { useSearchParams } from "next/navigation";
import { useResearch } from "@/hooks/useResearch";

export default function ResearchPage() {
  const searchParams = useSearchParams();
  const ticker = searchParams.get("ticker");

  const { report, loading, error } = useResearch(ticker);

  if (loading) {
    return (
      <main className="min-h-screen bg-slate-950 px-6 py-12 text-white">
        <div className="mx-auto max-w-7xl">
          <p className="text-sm text-slate-400">
            Generating research report...
          </p>
        </div>
      </main>
    );
  }

  if (error) {
    return (
      <main className="min-h-screen bg-slate-950 px-6 py-12 text-white">
        <div className="mx-auto max-w-7xl">
          <div className="rounded-xl border border-red-900/50 bg-red-950/20 p-6">
            <h1 className="text-lg font-semibold text-red-300">
              Research generation failed
            </h1>

            <p className="mt-2 text-sm text-red-400">
              {error}
            </p>
          </div>
        </div>
      </main>
    );
  }

  if (!ticker) {
    return (
      <main className="min-h-screen bg-slate-950 px-6 py-12 text-white">
        <div className="mx-auto max-w-7xl">
          <h1 className="text-2xl font-semibold">
            No company selected
          </h1>

          <p className="mt-2 text-slate-400">
            Search for a company to generate a research report.
          </p>
        </div>
      </main>
    );
  }

  if (!report) {
    return (
      <main className="min-h-screen bg-slate-950 px-6 py-12 text-white">
        <div className="mx-auto max-w-7xl">
          <p className="text-sm text-slate-400">
            No research report available.
          </p>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-950 px-6 py-12 text-white">
      <div className="mx-auto max-w-7xl">
        <p className="text-sm font-bold uppercase tracking-[0.25em] text-slate-300">
          FINTENDO
        </p>

        <h1 className="mt-4 text-3xl font-semibold tracking-tight">
          {report.ticker} Research Report
        </h1>

        <p className="mt-2 text-sm text-slate-500">
          Generated {new Date(report.generated_at).toLocaleString()}
        </p>

        <div className="mt-10 rounded-xl border border-slate-800 bg-slate-900 p-6">
          <h2 className="text-lg font-semibold">
            Committee Decision
          </h2>

          <p className="mt-4 text-2xl font-semibold">
            {report.committee.recommendation}
          </p>

          <p className="mt-2 text-slate-400">
            Conviction: {report.committee.conviction.toFixed(0)}%
          </p>

          <p className="mt-4 leading-7 text-slate-300">
            {report.committee.rationale}
          </p>
        </div>

        <div className="mt-6 rounded-xl border border-slate-800 bg-slate-900 p-6">
          <h2 className="text-lg font-semibold">
            Fundamental Analysis
          </h2>

          <p className="mt-4 text-3xl font-semibold">
            {report.fundamental.score.toFixed(1)}
          </p>

          <p className="mt-4 leading-7 text-slate-300">
            {report.fundamental.summary}
          </p>
        </div>

        <div className="mt-6 rounded-xl border border-slate-800 bg-slate-900 p-6">
          <h2 className="text-lg font-semibold">
            Technical Analysis
          </h2>

          <p className="mt-4 text-3xl font-semibold">
            {report.technical.score.toFixed(1)}
          </p>

          <p className="mt-4 leading-7 text-slate-300">
            {report.technical.summary}
          </p>
        </div>

        {report.market_intelligence && (
          <div className="mt-6 rounded-xl border border-slate-800 bg-slate-900 p-6">
            <h2 className="text-lg font-semibold">
              Market Intelligence
            </h2>

            <p className="mt-4 text-3xl font-semibold">
              {report.market_intelligence.score.toFixed(1)}
            </p>

            <p className="mt-4 leading-7 text-slate-300">
              {report.market_intelligence.summary}
            </p>
          </div>
        )}
      </div>
    </main>
  );
}